data.minimal_example:
final counter = Creator.value(0);

Widget build(BuildContext context) {
  return Column(
    children: [
      Watcher((context, ref, _) => Text('${ref.watch(counter)}')),
      TextButton(
        onPressed: () => context.ref.update<int>(counter, (c) => c + 1),
        child: const Text('+1'),
      ),
    ],
  );
}
